package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome330 {
    data class Success(val payload: String) : Outcome330()
    data object Failure : Outcome330()
}

fun describe330(outcome: Outcome330): String = when (outcome) {
    is Outcome330.Success -> outcome.payload
    Outcome330.Failure -> "failed"
}
class Counter331 {
    var current: Int by Delegates.observable(53) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
@JvmName("step332")
fun step332(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 60
}
